-- Migrasi multi-cabang EK Quotation Generator
-- Jalankan sekali di Supabase SQL Editor.

create table if not exists public.branches (
  code text primary key,
  name text not null,
  number_infix text not null default '',
  kop_img text,          -- base64 data URI; NULL = fallback kop pusat di app
  cap_img text,          -- base64 data URI; NULL = fallback cap pusat di app
  kop_aspect numeric     -- rasio W/H kop; NULL = fallback KOP_ASPECT di app
);
alter table public.branches enable row level security;
drop policy if exists branches_read on public.branches;
create policy branches_read on public.branches
  for select to authenticated using (true);

create table if not exists public.profiles (
  user_id uuid primary key references auth.users(id) on delete cascade,
  branch_code text not null references branches(code),
  display_name text
);
alter table public.profiles enable row level security;
drop policy if exists profiles_read_own on public.profiles;
create policy profiles_read_own on public.profiles
  for select to authenticated using (user_id = auth.uid());

insert into public.branches (code, name, number_infix, kop_img, kop_aspect) values
  ('PST', 'Pusat - Mangga Dua', '', NULL, NULL),
  ('DPK', 'Cabang Depok - Margonda', 'DPK', 'data:image/png;base64,', 5.5652),
  ('BKS', 'Cabang Bekasi - Summarecon', 'BKS', 'data:image/png;base64,', 5.5054),
  ('GSP', 'Cabang BSD - Gading Serpong', 'GSP', 'data:image/png;base64,', 5.9883),
  ('BTR', 'Cabang Bintaro - Bintaro Jaya', 'BTR', 'data:image/png;base64,', 5.1717)
on conflict (code) do update set
  name = excluded.name,
  number_infix = excluded.number_infix,
  kop_img = excluded.kop_img,
  kop_aspect = excluded.kop_aspect;

